#!/usr/bin/env node
// @ts-check
// qa-skills' one mechanical seam (ADR-0008).
// Zero dependencies. Every mode prints one JSON object on stdout, `mode` first; skills read it and
// never re-derive its results.
//
//   node scan.mjs <mode> [<action>] [<argument>...] [--<option> [<value>]]...
//
// Each mode is a command module, named in lib/modes.mjs, which declares its actions, the options
// each takes, its synopsis and its refusals, and documents what each prints; lib/cli.mjs runs one
// call against it. A bare or unknown mode prints every synopsis.
//
// A usage error prints `{mode, ok: false, error}` and exits 2; `design`, `impact`, `init` and `sync`
// word their own, `{mode, ok: false, text}`. A `.qa/` whose `project.md` declares a newer
// `schema_version` than this CLI reads, or a malformed one, is refused by every command that writes
// into the repository, `{mode, ok: false, text}`, exit 1, writing nothing; `scan` runs on, warning
// of a newer one (lib/schema-guard.mjs).
//
// `--root` names the `.qa/` directory (default ./.qa). Every run dir is named by `--dir` and printed
// back absolute (lib/run-dir.mjs); `impact plan`, `design split` and `design plan` still take
// `--out`, its deprecated old name.
import { readFileSync } from "node:fs";
import { runCommand } from "./lib/cli.mjs";
import { MODES } from "./lib/modes.mjs";

const { exit, json } = await runCommand(MODES, process.argv.slice(2), { env: process.env, input: () => readFileSync(0, "utf8") });
process.stdout.write(`${JSON.stringify(json, null, 2)}\n`);
process.exitCode = exit;

// @ts-check
// Parent-run setup for guard-denial, from the saved run.json, before the own Tester launches. It
// turns two of the Tester's ordinary calls into ones the guard must refuse, without telling the
// Tester anything: the own Execution's `.playwright-cli/` becomes a link to a directory outside
// it (so Reading an artifact a command printed is refused), and its report path becomes a link
// to a missing file outside it (so writing its report is refused). It records both in
// evidence/planted.json.
import {
  existsSync,
  lstatSync,
  mkdirSync,
  readFileSync,
  renameSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import { REPORT_FILE } from "../../plugin/scripts/lib/execution-guard.mjs";

/** @typedef {{artifacts: string, report: string}} Planted */

/** @param {string} stateDir @returns {Planted} */
export function plant(stateDir) {
  const manifest = /** @type {import("./evidence.mjs").Manifest} */ (
    JSON.parse(readFileSync(join(stateDir, "evidence/run.json"), "utf8"))
  );
  const exec = join(manifest.ownRun, "executions", manifest.ownId);
  if (!lstatSync(join(exec, "guard.json")).isFile()) throw new Error("the own Execution is not open");
  const outside = dirname(manifest.outsideRead);
  /** @type {Planted} */
  const planted = { artifacts: join(exec, ".playwright-cli"), report: join(exec, REPORT_FILE) };
  if (existsSync(join(outside, "evidence/planted.json")))
    throw new Error("the probe state is already planted");
  if (existsSync(planted.report)) throw new Error(`${planted.report} is already in use`);
  const moved = join(outside, "outside-artifacts");
  /** @type {import("node:fs").Stats | undefined} */
  let artifacts;
  try {
    artifacts = lstatSync(planted.artifacts);
  } catch {
    artifacts = undefined;
  }
  // execute open has already written its setup snapshots there: they move with the directory.
  if (artifacts?.isDirectory()) renameSync(planted.artifacts, moved);
  else if (artifacts) throw new Error(`${planted.artifacts} is already in use`);
  else mkdirSync(moved, { recursive: true });
  symlinkSync(moved, planted.artifacts);
  // The report link dangles. A host that refuses to overwrite an existing file the Tester has not
  // read (Claude Code 2.1.321 does, before any PreToolUse hook) would stop the Write itself, and
  // the guard would never see it. A missing target is a new file to the host, so the guard decides.
  symlinkSync(join(outside, "outside-report.md"), planted.report);
  writeFileSync(join(outside, "evidence/planted.json"), `${JSON.stringify(planted, null, 2)}\n`);
  return planted;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    process.stdout.write(`${JSON.stringify(plant(process.argv[2]))}\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
  }
}

